import java.util.*;

class AuthenticationManager {
    private final int timeToLive;
    private final Map<String, Integer> expiryByToken;

    public AuthenticationManager(int timeToLive) {
        this.timeToLive = timeToLive;
        expiryByToken = new HashMap<>();
    }

    public void generate(String tokenId, int currentTime) {
        expiryByToken.put(tokenId, currentTime + timeToLive);
    }

    public void renew(String tokenId, int currentTime) {
        Integer expiry = expiryByToken.get(tokenId);
        if (expiry != null && expiry > currentTime) {
            expiryByToken.put(tokenId, currentTime + timeToLive);
        }
    }

    public int countUnexpiredTokens(int currentTime) {
        int count = 0;
        for (int expiry : expiryByToken.values()) {
            if (expiry > currentTime) {
                count++;
            }
        }
        return count;
    }
}

import java.util.*;

class AuthenticationManager {
    private static final class Event {
        final String tokenId;
        final int expiry;

        Event(String tokenId, int expiry) {
            this.tokenId = tokenId;
            this.expiry = expiry;
        }
    }

    private final int timeToLive;
    private final Map<String, Integer> latestExpiry = new HashMap<>();
    private final ArrayDeque<Event> expiryEvents = new ArrayDeque<>();

    public AuthenticationManager(int timeToLive) {
        this.timeToLive = timeToLive;
    }

    public void generate(String tokenId, int currentTime) {
        cleanup(currentTime);
        addVersion(tokenId, currentTime + timeToLive);
    }

    public void renew(String tokenId, int currentTime) {
        cleanup(currentTime);
        Integer expiry = latestExpiry.get(tokenId);
        if (expiry != null && expiry > currentTime) {
            addVersion(tokenId, currentTime + timeToLive);
        }
    }

    public int countUnexpiredTokens(int currentTime) {
        cleanup(currentTime);
        return latestExpiry.size();
    }

    private void addVersion(String tokenId, int expiry) {
        latestExpiry.put(tokenId, expiry);
        expiryEvents.addLast(new Event(tokenId, expiry));
    }

    private void cleanup(int currentTime) {
        while (!expiryEvents.isEmpty() && expiryEvents.peekFirst().expiry <= currentTime) {
            Event event = expiryEvents.removeFirst();
            Integer current = latestExpiry.get(event.tokenId);
            if (current != null && current.equals(event.expiry)) {
                latestExpiry.remove(event.tokenId);
            }
        }
    }
}

