class AuthenticationManager {
    private final int timeToLive;
    private final LinkedHashMap<String, Integer> tokens = new LinkedHashMap<>();

    public AuthenticationManager(int timeToLive) {
        this.timeToLive = timeToLive;
    }

    public void generate(String tokenId, int currentTime) {
        removeExpired(currentTime);
        tokens.put(tokenId, currentTime + timeToLive);
    }

    public void renew(String tokenId, int currentTime) {
        removeExpired(currentTime);
        Integer expiry = tokens.get(tokenId);
        if (expiry == null || expiry <= currentTime) {
            return;
        }
        tokens.remove(tokenId);
        tokens.put(tokenId, currentTime + timeToLive);
    }

    public int countUnexpiredTokens(int currentTime) {
        removeExpired(currentTime);
        return tokens.size();
    }

    private void removeExpired(int currentTime) {
        Iterator<Map.Entry<String, Integer>> iterator = tokens.entrySet().iterator();
        while (iterator.hasNext()) {
            Map.Entry<String, Integer> first = iterator.next();
            if (first.getValue() > currentTime) {
                break;
            }
            iterator.remove();
        }
    }
}

import java.util.*;

class AuthenticationManager {
    private final int timeToLive;
    private final Map<String, Integer> expiryByToken = new HashMap<>();
    private final TreeMap<Integer, Set<String>> tokensByExpiry = new TreeMap<>();

    public AuthenticationManager(int timeToLive) {
        this.timeToLive = timeToLive;
    }

    public void generate(String tokenId, int currentTime) {
        cleanup(currentTime);
        putToken(tokenId, currentTime + timeToLive);
    }

    public void renew(String tokenId, int currentTime) {
        cleanup(currentTime);
        Integer oldExpiry = expiryByToken.get(tokenId);
        if (oldExpiry == null || oldExpiry <= currentTime) {
            return;
        }
        removeFromBucket(tokenId, oldExpiry);
        putToken(tokenId, currentTime + timeToLive);
    }

    public int countUnexpiredTokens(int currentTime) {
        cleanup(currentTime);
        return expiryByToken.size();
    }

    private void putToken(String tokenId, int expiry) {
        expiryByToken.put(tokenId, expiry);
        tokensByExpiry.computeIfAbsent(expiry, ignored -> new HashSet<>()).add(tokenId);
    }

    private void removeFromBucket(String tokenId, int expiry) {
        Set<String> bucket = tokensByExpiry.get(expiry);
        if (bucket != null) {
            bucket.remove(tokenId);
            if (bucket.isEmpty()) {
                tokensByExpiry.remove(expiry);
            }
        }
    }

    private void cleanup(int currentTime) {
        while (!tokensByExpiry.isEmpty() && tokensByExpiry.firstKey() <= currentTime) {
            Map.Entry<Integer, Set<String>> entry = tokensByExpiry.pollFirstEntry();
            int expiry = entry.getKey();
            for (String tokenId : entry.getValue()) {
                Integer current = expiryByToken.get(tokenId);
                if (current != null && current == expiry) {
                    expiryByToken.remove(tokenId);
                }
            }
        }
    }
}

import java.util.*;

class AuthenticationManager {
    private static final class ExpiryEvent {
        final String tokenId;
        final int expiry;

        ExpiryEvent(String tokenId, int expiry) {
            this.tokenId = tokenId;
            this.expiry = expiry;
        }
    }

    private final int timeToLive;
    private final Map<String, Integer> latestExpiry = new HashMap<>();
    private final PriorityQueue<ExpiryEvent> heap = new PriorityQueue<>(Comparator.comparingInt(event -> event.expiry));

    public AuthenticationManager(int timeToLive) {
        this.timeToLive = timeToLive;
    }

    public void generate(String tokenId, int currentTime) {
        expireUpTo(currentTime);
        schedule(tokenId, currentTime + timeToLive);
    }

    public void renew(String tokenId, int currentTime) {
        expireUpTo(currentTime);
        Integer expiry = latestExpiry.get(tokenId);
        if (expiry != null && expiry > currentTime) {
            schedule(tokenId, currentTime + timeToLive);
        }
    }

    public int countUnexpiredTokens(int currentTime) {
        expireUpTo(currentTime);
        return latestExpiry.size();
    }

    private void schedule(String tokenId, int expiry) {
        latestExpiry.put(tokenId, expiry);
        heap.offer(new ExpiryEvent(tokenId, expiry));
    }

    private void expireUpTo(int currentTime) {
        while (!heap.isEmpty() && heap.peek().expiry <= currentTime) {
            ExpiryEvent event = heap.poll();
            if (Integer.valueOf(event.expiry).equals(latestExpiry.get(event.tokenId))) {
                latestExpiry.remove(event.tokenId);
            }
        }
    }
}
